-- Add department column to cbt_questions if not exists
ALTER TABLE public.cbt_questions ADD COLUMN IF NOT EXISTS department text;

-- Insert review cycles
-- Q3 2025 (Closed)
VALUES ('aaaaaaaa-0001-4000-a000-000000000003', 'Q3 2025 Performance Review', '2025-07-01', '2025-09-30', 'quarterly', 'closed')
ON CONFLICT (id) DO UPDATE 
SET name = EXCLUDED.name, status = EXCLUDED.status, start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date;

-- Q4 2025 (Active)
VALUES ('aaaaaaaa-0001-4000-a000-000000000004', 'Q4 2025 Performance Review', '2025-10-01', '2025-12-31', 'quarterly', 'active')
ON CONFLICT (id) DO UPDATE 
SET name = EXCLUDED.name, status = EXCLUDED.status, start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date;

-- Close other cycles to ensure only Q4 2025 is active as requested
UPDATE public.review_cycles 
SET status = 'closed' 
WHERE id != 'aaaaaaaa-0001-4000-a000-000000000004';

